const results = JSON.parse(localStorage.getItem('highlights')) || [];

function scoreRecord(record) {
  return record.intensity * 2 + record.chatRate;
}

function renderTable(data) {
  const tableBody = document.getElementById('resultsTable');
  tableBody.innerHTML = '';
  data.forEach(record => {
    const row = document.createElement('tr');
    row.innerHTML = `<td>${record.streamer}</td><td>${record.game}</td><td>${record.category}</td><td>${record.score}</td>`;
    tableBody.appendChild(row);
  });
}

function applyFilters() {
  const streamer = document.getElementById('filterStreamer').value.toLowerCase();
  const game = document.getElementById('filterGame').value.toLowerCase();
  const category = document.getElementById('filterCategory').value.toLowerCase();
  const minScore = parseInt(document.getElementById('filterScore').value, 10) || 0;

  const filtered = results.filter(record => (
    (!streamer || record.streamer.toLowerCase().includes(streamer)) &&
    (!game || record.game.toLowerCase().includes(game)) &&
    (!category || record.category.toLowerCase().includes(category)) &&
    record.score >= minScore
  ));

  renderTable(filtered);
}

document.getElementById('applyFilters').addEventListener('click', applyFilters);

document.getElementById('manualForm').addEventListener('submit', event => {
  event.preventDefault();
  const formData = new FormData(event.target);
  const newRecord = {
    streamer: formData.get('streamer'),
    game: formData.get('game'),
    category: formData.get('category'),
    score: parseInt(formData.get('score'), 10)
  };
  results.push(newRecord);
  localStorage.setItem('highlights', JSON.stringify(results));
  renderTable(results);
  event.target.reset();
});

document.getElementById('exportData').addEventListener('click', () => {
  const blob = new Blob([JSON.stringify(results, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'highlights.json';
  a.click();
  URL.revokeObjectURL(url);
});

renderTable(results);
